import 'package:flutter/material.dart';\nimport 'package:flutter_riverpod/flutter_riverpod.dart';\nimport '../../../core/providers/core_providers.dart';\nimport '../providers/schedule_providers.dart';\n\nclass ScheduleTab extends ConsumerWidget {\n  const ScheduleTab({Key? key}) : super(key: key);\n\n  @override\n  Widget build(BuildContext context, WidgetRef ref) {\n    final localStorage = ref.watch(localStorageServiceProvider);\n    final gradeId = localStorage.getSelectedGrade();\n\n    if (gradeId == null) {\n      return const Center(child: Text('خطأ: الصف غير محدد'));\n    }\n\n    final scheduleAsync = ref.watch(scheduleProvider(gradeId));\n\n    return Scaffold(\n      appBar: AppBar(\n        title: const Text('جدول الحصص الأسبوعي'),\n        centerTitle: true,\n      ),\n      body: scheduleAsync.when(\n        data: (schedule) {\n          if (schedule == null || schedule.scheduleData.isEmpty) {\n            return const Center(child: Text('لم يتم رفع جدول لهذا الصف بعد.'));\n          }\n          \n          final days = ['الأحد', 'الإثنين', 'الثلاثاء', 'الأربعاء', 'الخميس'];\n          \n          return ListView.builder(\n            padding: const EdgeInsets.all(16),\n            itemCount: days.length,\n            itemBuilder: (context, index) {\n              final day = days[index];\n              final lessons = List<String>.from(schedule.scheduleData[day] ?? []);\n              \n              if (lessons.isEmpty) return const SizedBox.shrink();\n\n              return Card(\n                margin: const EdgeInsets.only(bottom: 16),\n                elevation: 3,\n                shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(12)),\n                child: Padding(\n                  padding: const EdgeInsets.all(16.0),\n                  child: Column(\n                    crossAxisAlignment: CrossAxisAlignment.start,\n                    children: [\n                      Text(\n                        day,\n                        style: const TextStyle(fontSize: 20, fontWeight: FontWeight.bold, color: Colors.blue),\n                      ),\n                      const Divider(),\n                      const SizedBox(height: 8),\n                      Wrap(\n                        spacing: 8,\n                        runSpacing: 8,\n                        children: List.generate(lessons.length, (i) {\n                          return Chip(\n                            label: Text('${i + 1}- ${lessons[i]}'),\n                            backgroundColor: Colors.blue.shade50,\n                          );\n                        }),\n                      )\n                    ],\n                  ),\n                ),\n              );\n            },\n          );\n        },\n        loading: () => const Center(child: CircularProgressIndicator()),\n        error: (err, stack) => Center(child: Text('خطأ: $err')),\n      ),\n    );\n  }\n}\n